.kickoff-wrap{max-width:1120px;margin:0 auto;padding:18px 10px 30px}.kickoff-wrap h2{margin-top:0;font-size:30px}.kickoff-card{background:#fff;border:1px solid #dfe4ea;border-radius:14px;padding:18px;margin:14px 0;box-shadow:0 3px 12px rgba(0,0,0,.06)}.kickoff-hero{display:flex;align-items:center;justify-content:space-between;background:linear-gradient(135deg,#fff,#f4fbff);border-left:6px solid #1687a7}.kickoff-hero h2{margin:4px 0 8px}.kickoff-hero p{margin:0;color:#566}.kickoff-kicker{text-transform:uppercase;letter-spacing:.08em;font-size:12px;font-weight:700;color:#1687a7}.kickoff-hero-icon{font-size:48px;color:#1687a7;opacity:.85}.kickoff-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:14px}.kickoff-tile{display:flex;flex-direction:column;gap:8px;text-decoration:none!important;color:#17202a!important;min-height:145px;transition:transform .12s ease,box-shadow .12s ease,border-color .12s ease}.kickoff-tile:hover{transform:translateY(-2px);box-shadow:0 8px 18px rgba(0,0,0,.12);border-color:#1687a7}.kickoff-tile i{font-size:28px;color:#1687a7}.kickoff-tile strong{display:block;font-size:20px}.kickoff-tile span{color:#58656f;line-height:1.35}.kickoff-tile em{margin-top:auto;font-style:normal;font-weight:700;color:#1687a7}.kickoff-tile-primary{border-left:6px solid #1687a7}.kickoff-muted{color:#6c757d}.kickoff-warning{border-left:5px solid #f0ad4e}.kickoff-page-head{margin-bottom:14px}.kickoff-page-head h2{margin:10px 0 6px}.kickoff-back{display:inline-flex;align-items:center;text-decoration:none!important;background:#eef6f8;border:1px solid #cde5ec;border-radius:999px;padding:7px 12px;color:#11677d!important;font-weight:700}.kickoff-select-card label,.kickoff-field label{display:block;font-weight:700;margin-bottom:6px}.kickoff-match-meta{display:flex;gap:12px;color:#6c757d;font-size:13px;margin-bottom:12px;flex-wrap:wrap}.kickoff-match-row{display:grid;grid-template-columns:minmax(170px,1fr) 74px 18px 74px minmax(170px,1fr);align-items:center;gap:10px}.kickoff-team{font-weight:700;font-size:16px}.kickoff-home{text-align:right}.kickoff-away{text-align:left}.kickoff-score{width:74px!important;max-width:74px;text-align:center;font-size:22px;font-weight:700;border:2px solid #ccd6dd!important;border-radius:8px!important;padding:6px!important;background:#fff!important}.kickoff-score:focus{border-color:#1687a7!important;box-shadow:0 0 0 3px rgba(22,135,167,.15)!important;outline:none}.kickoff-sep{text-align:center;font-weight:700;color:#6c757d}.kickoff-status{font-size:13px;color:#6c757d;margin-top:10px;min-height:18px}.kickoff-status:not(:empty){background:#f6f8fa;border-radius:8px;padding:7px 9px}.kickoff-error{color:#b00020}.kickoff-pill{background:#f1f3f5;border-radius:999px;padding:3px 9px;font-weight:700}.kickoff-stage{margin:26px 0 10px;border-bottom:1px solid #dfe4ea;padding-bottom:8px}.kickoff-table-wrap{overflow-x:auto}.kickoff-table{width:100%;border-collapse:separate;border-spacing:0}.kickoff-table th{background:#f3f7f9;color:#344;text-align:left}.kickoff-table th,.kickoff-table td{padding:11px;border-bottom:1px solid #e9ecef}.kickoff-rank{display:inline-flex;align-items:center;justify-content:center;min-width:30px;height:30px;border-radius:999px;background:#eef6f8;color:#11677d;font-weight:700}.kickoff-empty{color:#6c757d}.kickoff-result-form{display:flex;gap:8px;align-items:center;border-bottom:1px solid #eee;padding:8px 0;flex-wrap:wrap}.kickoff-result-form input[type=number]{width:70px}.kickoff-admin-match{min-width:320px;flex:1}.kickoff-inline-form{margin-bottom:12px}.kickoff-pick-row{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.kickoff-pick-row strong{min-width:220px}.kickoff-winner-pick{max-width:360px}.kickoff-admin-select{max-width:260px;display:inline-block;margin:0 8px}.kickoff-bonus-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.kickoff-field{margin-bottom:14px}.kickoff-save-button{margin-top:8px}@media(max-width:700px){.kickoff-wrap{padding:12px 8px}.kickoff-hero{align-items:flex-start}.kickoff-hero-icon{display:none}.kickoff-match-row{grid-template-columns:1fr 58px 14px 58px 1fr;gap:6px}.kickoff-score{width:58px!important;max-width:58px;font-size:18px}.kickoff-team{font-size:14px}.kickoff-card{padding:13px;border-radius:12px}.kickoff-admin-match{min-width:100%}}
.kickoff-admin-wrap{max-width:1160px}.kickoff-admin-hero{display:flex;align-items:center;justify-content:space-between;background:linear-gradient(135deg,#fff,#f7fbff);border-left:6px solid #1687a7}.kickoff-admin-hero h2{margin:4px 0 8px}.kickoff-admin-hero p{margin:0;color:#566}.kickoff-admin-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.kickoff-admin-card-head{display:flex;gap:14px;align-items:flex-start;margin-bottom:14px}.kickoff-admin-card-head>i{font-size:30px;color:#1687a7;background:#eef8fb;border-radius:14px;width:54px;height:54px;display:flex;align-items:center;justify-content:center;flex:0 0 54px}.kickoff-admin-card-head h3{margin:0 0 6px}.kickoff-admin-card-head p{margin:0;color:#60707a;line-height:1.35}.kickoff-admin-actions{margin-top:12px;display:flex;gap:10px;align-items:center;flex-wrap:wrap}.kickoff-admin-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.kickoff-stat{margin:0;text-align:center}.kickoff-stat strong{display:block;font-size:34px;line-height:1;color:#1687a7}.kickoff-stat span{display:block;margin-top:7px;color:#60707a;font-weight:700}.kickoff-admin-current-main{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}.kickoff-admin-current h3{margin:4px 0 8px}.kickoff-admin-actions-right{justify-content:flex-end;min-width:260px}.kickoff-admin-results-list{border:1px solid #edf0f2;border-radius:12px;overflow:hidden}.kickoff-admin-results-list .kickoff-result-form{margin:0;border-bottom:1px solid #edf0f2;padding:10px 12px;background:#fff}.kickoff-admin-results-list .kickoff-result-form:nth-child(even){background:#fafcfd}.kickoff-admin-results-list .kickoff-result-form:last-child{border-bottom:0}.kickoff-admin-match{display:flex;flex-direction:column;gap:3px;min-width:300px}.kickoff-admin-match-id{display:inline-flex;width:max-content;background:#eef6f8;color:#11677d;font-size:12px;font-weight:700;border-radius:999px;padding:2px 8px}.kickoff-admin-match small{color:#78858d}.kickoff-admin-result-inputs{display:flex;gap:8px;align-items:center;margin-left:auto;flex-wrap:wrap}.kickoff-admin-result-inputs input[type=number]{width:68px;text-align:center;border:1px solid #cfd8df;border-radius:7px;padding:6px}.kickoff-admin-select{min-width:240px}.kickoff-admin-results-card{padding-bottom:22px}@media(max-width:900px){.kickoff-admin-grid,.kickoff-admin-stats{grid-template-columns:1fr 1fr}.kickoff-admin-current-main{flex-direction:column}.kickoff-admin-actions-right{justify-content:flex-start;min-width:0}.kickoff-admin-result-inputs{margin-left:0}}@media(max-width:560px){.kickoff-admin-grid,.kickoff-admin-stats{grid-template-columns:1fr}.kickoff-admin-hero .kickoff-hero-icon{display:none}.kickoff-admin-card-head{gap:10px}.kickoff-admin-match{min-width:100%}.kickoff-admin-result-inputs{width:100%}}

.kickoff-admin-import-grid{margin-top:14px}.kickoff-team-preview{display:flex;flex-wrap:wrap;gap:7px;margin:10px 0 12px}.kickoff-team-chip{display:inline-flex;align-items:center;gap:5px;background:#eef6f8;color:#11677d;border:1px solid #d4eaf0;border-radius:999px;padding:5px 10px;font-weight:700;font-size:13px}.kickoff-team-more{background:#f1f3f5;color:#5f6b73;border-color:#e0e4e7}.kickoff-upload-form{margin-top:12px;border-top:1px solid #edf0f2;padding-top:12px}.kickoff-upload-form label{display:block;font-weight:700;margin-bottom:6px}.kickoff-upload-form input[type=file]{margin-bottom:10px}.kickoff-match-preview{display:grid;gap:8px;margin:10px 0}.kickoff-mini-match{background:#f8fbfc;border:1px solid #edf0f2;border-radius:10px;padding:8px 10px;display:flex;justify-content:space-between;gap:10px;align-items:center}.kickoff-mini-match span{color:#6c757d;font-size:12px;white-space:nowrap}

.kickoff-filterbar{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.kickoff-filter{border:1px solid #cde5ec;background:#fff;color:#11677d;border-radius:999px;padding:7px 12px;font-weight:700}.kickoff-filter.active,.kickoff-filter:hover{background:#1687a7;color:#fff}.kickoff-admin-filterbar{display:flex;gap:10px;flex-wrap:wrap;margin:8px 0 14px}.kickoff-admin-filterbar .form-control{max-width:220px}.kickoff-admin-editor summary{cursor:pointer;font-size:18px;font-weight:700;color:#17202a}.kickoff-edit-list{margin-top:14px;display:grid;gap:8px}.kickoff-edit-row{display:grid;grid-template-columns:110px 70px minmax(190px,1.2fr) minmax(140px,1fr) minmax(120px,.8fr) 110px 80px;gap:8px;align-items:center;background:#f8fbfc;border:1px solid #edf0f2;border-radius:10px;padding:8px}.kickoff-edit-row input,.kickoff-edit-row select,.kickoff-edit-row textarea{border:1px solid #cfd8df;border-radius:7px;padding:6px;width:100%}.kickoff-edit-match-row{grid-template-columns:140px minmax(150px,1fr) minmax(170px,1fr) minmax(170px,1fr) 90px 90px 110px minmax(190px,1fr) auto}.kickoff-edit-match-row textarea{grid-column:2 / span 7}.kickoff-danger-card{border-left:6px solid #dc3545}.kickoff-danger-card h3{margin-top:0}.kickoff-danger-card form{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.kickoff-reset-input{max-width:160px}.kickoff-hidden{display:none!important}@media(max-width:900px){.kickoff-edit-row,.kickoff-edit-match-row{grid-template-columns:1fr}.kickoff-edit-match-row textarea{grid-column:auto}.kickoff-admin-filterbar .form-control{max-width:none}}
.kickoff-share{display:grid;grid-template-columns:220px 1fr;gap:10px;align-items:center}.kickoff-share strong{color:#11677d}.kickoff-share-input{font-size:13px;background:#f8fbfc!important}.kickoff-score:disabled,.kickoff-winner-pick:disabled{background:#f1f3f5!important;color:#5f6b73!important;cursor:not-allowed}@media(max-width:700px){.kickoff-share{grid-template-columns:1fr}.kickoff-share-input{font-size:12px}}
.kickoff-admin-table-wrap{overflow-x:auto;margin-top:12px}.kickoff-admin-prediction-table td small{display:block;color:#6c757d;margin-top:4px}.kickoff-prediction-pill{display:inline-block;background:#eef6f8;border:1px solid #cde5ec;border-radius:999px;padding:4px 10px;font-weight:700;color:#11677d}.kickoff-admin-predictions summary{cursor:pointer;font-weight:700;font-size:18px}.kickoff-admin-predictions summary i{color:#1687a7;margin-right:8px}
